function pageAfter(items, cursor, limit) {
    // Validate limit
    if (limit !== Math.floor(limit) || limit < 1 || limit > 100) {
        throw new RangeError("limit must be an integer between 1 and 100");
    }

    // Validate cursor and find starting index
    let startIndex = 0;
    if (cursor !== null) {
        const cursorIndex = items.findIndex(item => item.id === cursor);
        if (cursorIndex === -1) {
            throw new RangeError("Unknown cursor position");
        }
        startIndex = cursorIndex + 1;
    }

    // Calculate end index and slice items
    const endIndex = Math.min(startIndex + limit, items.length);

    // Build result
    const pageItems = items.slice(startIndex, endIndex).map(item => ({ ...item }));

    return {
        items: pageItems,
        nextCursor: endIndex < items.length ? items[endIndex].id : null
    };
}

